{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, COUNT(*) n, SUM(CASE WHEN duration>100000000 THEN 1 ELSE 0 END) over100ms, ROUND(quantile_cont(duration,0.5)/1e6,2) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' UNION ALL SELECT 'nor', COUNT(*), SUM(CASE WHEN duration>100000000 THEN 1 ELSE 0 END), ROUND(quantile_cont(duration,0.5)/1e6,2), ROUND(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other'",
          "claim": "ts-order-other SELECT ts.orders_other p95 rose from 0.4ms to 415.6ms; 116 of 387 calls exceed 100ms, versus none before."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_pod_name pod, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,1) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','OrderOtherRepository.findByAccountId','Transaction.commit') GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Slowness sits in the database spans (SELECT and Transaction.commit) on the single order-other pod; the repository calls inherit it."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, ROUND(AVG(value),2) avg_v, ROUND(MAX(value),2) max_v FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('container.cpu.usage','k8s.pod.memory.working_set','k8s.pod.cpu_limit_utilization','k8s.pod.memory_limit_utilization') GROUP BY 1",
          "claim": "ts-order-other container CPU and memory stay low and flat during the incident, so no resource saturation explains the slowness."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, p.service_name parent_svc, COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND c.attr_span_kind='Server' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2,3",
          "claim": "Dashboard's POST orderOther/refresh calls to order-other reach 634ms p95 in the incident, versus about 3ms before."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, p.service_name parent_svc, COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND c.attr_span_kind='Server' AND p.service_name='ts-admin-order-service' GROUP BY 1,2,3",
          "claim": "Admin-order's calls into order-other take about 565ms p95, and admin-order's own GET adminorder spans are slow too."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, p.service_name parent_svc, COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-admin-order-service' AND c.attr_span_kind='Server' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2,3",
          "claim": "Dashboard's GET adminorder calls to admin-order-service reach about 645ms p95 during the incident."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-security-service' AND span_name IN ('GET','SecurityController.check') GROUP BY 1,2,3",
          "claim": "Security's outbound GET calls and SecurityController.check reach about 1.1-1.2s p95 during the incident, versus about 10-21ms before."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name IN ('GET','PreserveController.preserve') GROUP BY 1,2,3",
          "claim": "Preserve's outbound GET calls to security and its preserve handler reach about 1.1-1.3s p95 in the incident, versus about 22-147ms before."
        }
      ]
    }
  ]
}
